// Throwaway harness: exercises app.js against a stubbed DOM to confirm the
// success path tracks an identity and the validation-failure path does not.
const fs = require("node:fs");
const vm = require("node:vm");

function run(username, password) {
  const fields = { username: { value: username }, password: { value: password } };
  let handler;
  const sandbox = {
    console,
    document: {
      getElementById: (id) =>
        id === "login-form"
          ? { addEventListener: (_e, fn) => { handler = fn; } }
          : fields[id],
    },
  };
  vm.createContext(sandbox);
  vm.runInContext(fs.readFileSync(process.argv[2], "utf8"), sandbox);
  handler({ preventDefault() {} });
}

console.log("--- valid submit ---");
run("alice", "hunter2");
console.log("--- invalid submit (no password) ---");
run("alice", "");

